mapper.select:
SELECT pc.id, pc.user_id, pc.product_id, pc.product_type, pc.product_count, pc.is_deleted, pc.product_price, pc.create_time, pc.update_time, pc.delete_time, u.nickname as userName, p.name as productName, p.images as productImages FROM product_cart pc LEFT JOIN user u ON pc.user_id = u.id LEFT JOIN product p ON pc.product_id = p.id
pc.is_deleted = 0
AND pc.user_id = #{queryParams.userId}
AND pc.product_id = #{queryParams.productId}
AND u.nickname LIKE CONCAT('%', #{queryParams.userName}, '%')
AND p.name LIKE CONCAT('%', #{queryParams.productName}, '%')
AND pc.product_type LIKE CONCAT('%', #{queryParams.productType}, '%')
AND pc.create_time >= #{queryParams.createTime[0]}
AND pc.create_time <= #{queryParams.createTime[1]}
ORDER BY pc.create_time DESC
